import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/cr_elements/cr_auto_img/cr_auto_img.js";import"./strings.m.js";import{CrButtonElement}from"chrome://resources/cr_elements/cr_button/cr_button.js";import{assert,assertInstanceof}from"chrome://resources/js/assert.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{getTemplate}from"./app_install_dialog.html.js";import{BrowserProxy}from"./browser_proxy.js";class AppInstallDialogElement extends HTMLElement{static get is(){return"app-install-dialog"}static get template(){return getTemplate()}proxy=BrowserProxy.getInstance();constructor(){super();const template=document.createElement("template");template.innerHTML=AppInstallDialogElement.template;const fragment=template.content.cloneNode(true);this.attachShadow({mode:"open"}).appendChild(fragment);this.initDynamicContent()}async initDynamicContent(){try{const dialogArgs=await this.proxy.handler.getDialogArgs();assert(dialogArgs.args);const nameElement=this.$("#name");assert(nameElement);nameElement.textContent=dialogArgs.args.name;const urlElement=this.$("#url");assert(urlElement);urlElement.textContent=dialogArgs.args.url.url;const descriptionElement=this.$("#description");assert(descriptionElement);descriptionElement.textContent=dialogArgs.args.description;const iconElement=this.$("#icon");assert(iconElement);iconElement.setAttribute("auto-src",dialogArgs.args.iconUrl.url)}catch(e){console.error(`Unable to get dialog arguments . Error: ${e}.`)}}$(query){return this.shadowRoot.querySelector(query)}connectedCallback(){const cancelButton=this.$(".cancel-button");assert(cancelButton);cancelButton.addEventListener("click",this.onCancelButtonClick.bind(this));const installButton=this.$(".install-button");assert(installButton);installButton.addEventListener("click",this.onInstallButtonClick.bind(this),{once:true})}onCancelButtonClick(){this.proxy.handler.closeDialog()}async onInstallButtonClick(event){assertInstanceof(event.target,CrButtonElement);const installButton=event.target;installButton.textContent=loadTimeData.getString("installing");installButton.classList.replace("install","installing");installButton.disabled=true;const[{installed:install_result}]=await Promise.all([this.proxy.handler.installApp(),new Promise((resolve=>setTimeout(resolve,2e3)))]);installButton.disabled=false;if(install_result){installButton.textContent="Open app";installButton.classList.replace("installing","installed");installButton.addEventListener("click",this.onOpenAppButtonClick.bind(this))}else{installButton.textContent=loadTimeData.getString("install");installButton.classList.replace("installing","install")}}async onOpenAppButtonClick(){this.proxy.handler.launchApp();this.proxy.handler.closeDialog()}}customElements.define(AppInstallDialogElement.is,AppInstallDialogElement);